void per_exec_register( Per_Exec_Func per_exec_func , ... )
{
 	va_list args ;

    per_exec_init();
    
    va_start( args , per_exec_func ) ;
	{
		reg_func_arg( per_exec_reg , 0 , (Reg_Func)per_exec_func , (Reg_Own_Arg)va_arg( args , VARG ) );
	}
	va_end( args ) ;    	
}

